#include "darc_internal.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <dirent.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>

extern char *realpath(const char *restrict, char *restrict);

typedef struct {uint64_t files,dirs,symlinks,hardlinks,bytes,chunks,recovered,skipped,hl_degraded;} RestoreStats;
static size_t test_restore_write_max=0;
static int restore_escape(const char*why){darc_error(DARC_E_RESTORE,"E_RESTORE_ESCAPE","%s",why);return DARC_E_RESTORE;}
static bool selected(const char*p,const char*f){if(!f||!*f)return true;size_t n=strlen(f),pn=strlen(p);return pn>=n&&!memcmp(p,f,n)&&(p[n]==0||p[n]=='/');}
static int split_parent(int rootfd,const char*path,bool create,int*parent,char**leaf){if(!darc_path_is_safe_archive(path))return restore_escape("unsafe archive path");char*copy=darc_strdup(path);if(!copy)return DARC_E_IO;int fd=dup(rootfd);if(fd<0){free(copy);return DARC_E_IO;}char*s=copy,*slash;while((slash=strchr(s,'/'))){*slash=0;if(!*s){close(fd);free(copy);return DARC_E_RESTORE;}int nfd=openat(fd,s,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(nfd<0&&errno==ENOENT&&create){if(mkdirat(fd,s,0700)&&errno!=EEXIST){close(fd);free(copy);return DARC_E_IO;}nfd=openat(fd,s,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);}if(nfd<0){int e=errno;close(fd);free(copy);errno=e;return (e==ELOOP||e==ENOTDIR)?restore_escape("destination parent is a symlink or non-directory"):DARC_E_IO;}close(fd);fd=nfd;s=slash+1;}if(!*s){close(fd);free(copy);return DARC_E_RESTORE;}*leaf=darc_strdup(s);free(copy);if(!*leaf){close(fd);return DARC_E_IO;}*parent=fd;return 0;}
static int rm_at(int pfd,const char*name){struct stat st;if(fstatat(pfd,name,&st,AT_SYMLINK_NOFOLLOW)){return errno==ENOENT?0:-1;}if(!S_ISDIR(st.st_mode)||S_ISLNK(st.st_mode))return unlinkat(pfd,name,0);int fd=openat(pfd,name,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(fd<0)return -1;DIR*d=fdopendir(fd);if(!d){close(fd);return -1;}struct dirent*de;int rc=0;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;if(rm_at(fd,de->d_name)){rc=-1;break;}}closedir(d);if(!rc)rc=unlinkat(pfd,name,AT_REMOVEDIR);return rc;}
static int prepare_replace(int pfd,const char*leaf,int policy,bool want_dir){struct stat st;if(fstatat(pfd,leaf,&st,AT_SYMLINK_NOFOLLOW)){return errno==ENOENT?0:DARC_E_IO;}bool isdir=S_ISDIR(st.st_mode)&&!S_ISLNK(st.st_mode);if(want_dir&&isdir)return 0;if(policy==0)return DARC_E_RESTORE;if(policy==1&&(want_dir||isdir))return DARC_E_RESTORE;if(policy==1){if(unlinkat(pfd,leaf,0))return DARC_E_IO;return 0;}if(rm_at(pfd,leaf))return DARC_E_IO;return 0;}
static struct timespec ns_timespec(int64_t ns){struct timespec t;t.tv_sec=(time_t)(ns/1000000000LL);t.tv_nsec=(long)(ns%1000000000LL);if(t.tv_nsec<0){t.tv_nsec+=1000000000L;t.tv_sec--;}return t;}
static int restore_file(const char*repo,int rootfd,const DarcFlatEnt*e,const DarcConfig*c,RestoreStats*st){int pfd;char*leaf=NULL;int rc=split_parent(rootfd,e->path,true,&pfd,&leaf);if(rc)return rc;struct stat ex;bool exists=fstatat(pfd,leaf,&ex,AT_SYMLINK_NOFOLLOW)==0;if(exists&&c->overwrite==0){close(pfd);free(leaf);return DARC_E_RESTORE;}if(exists&&c->overwrite==1&&S_ISDIR(ex.st_mode)){close(pfd);free(leaf);return DARC_E_RESTORE;}if(exists&&c->overwrite==2&&S_ISDIR(ex.st_mode)){if(rm_at(pfd,leaf)){close(pfd);free(leaf);return DARC_E_IO;}}
 char tmp[128];static unsigned long seq=0;snprintf(tmp,sizeof tmp,".darc-tmp-%ld-%lu",(long)getpid(),++seq);int fd=openat(pfd,tmp,O_CREAT|O_EXCL|O_WRONLY|O_NOFOLLOW|O_CLOEXEC,0600);if(fd<0){close(pfd);free(leaf);return DARC_E_IO;}DarcObject fo;rc=darc_object_load(repo,&e->cid,&fo,1);if(rc||fo.type!=OBJ_FILE){if(!rc)darc_object_free(&fo);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return rc?rc:DARC_E_CORRUPT;}DarcFileObj f;if(darc_file_parse(fo.payload.data,fo.payload.len,&f)){darc_object_free(&fo);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_CORRUPT;}darc_object_free(&fo);DarcSha256 sh;darc_sha256_init(&sh);uint64_t wrote=0;for(size_t i=0;i<f.chunk_n;i++){DarcBuf b;bool rec=false;rc=darc_chunk_read_or_recover(repo,&f.chunks[i].cid,&b,false,&rec);if(rc){darc_file_free(&f);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return rc;}if(b.len>test_restore_write_max)test_restore_write_max=b.len;if(b.len!=f.chunks[i].len||darc_write_all(fd,b.data,b.len)){darc_buf_free(&b);darc_file_free(&f);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_IO;}darc_sha256_update(&sh,b.data,b.len);wrote+=b.len;st->chunks++;if(rec)st->recovered++;darc_buf_free(&b);}uint8_t digest[32];darc_sha256_final(&sh,digest);if(wrote!=f.logical_size||memcmp(digest,f.digest,32)){darc_file_free(&f);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_CORRUPT;}if(c->preserve_mode&&fchmod(fd,(mode_t)e->mode)){darc_file_free(&f);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_IO;}if(c->preserve_mtime){struct timespec ts[2];ts[0].tv_nsec=UTIME_OMIT;ts[0].tv_sec=0;ts[1]=ns_timespec(e->mtime_ns);if(futimens(fd,ts)){darc_file_free(&f);close(fd);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_IO;}}if(darc_fsync_fd(fd)||close(fd)){darc_file_free(&f);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_IO;}if(renameat(pfd,tmp,pfd,leaf)){darc_file_free(&f);unlinkat(pfd,tmp,0);close(pfd);free(leaf);return DARC_E_IO;}darc_file_free(&f);st->files++;st->bytes+=wrote;close(pfd);free(leaf);return 0;}
static int ensure_dir(int rootfd,const DarcFlatEnt*e,const DarcConfig*c,RestoreStats*st){int pfd;char*leaf=NULL;int rc=split_parent(rootfd,e->path,true,&pfd,&leaf);if(rc)return rc;struct stat x;if(!fstatat(pfd,leaf,&x,AT_SYMLINK_NOFOLLOW)){if(!S_ISDIR(x.st_mode)||S_ISLNK(x.st_mode)){rc=prepare_replace(pfd,leaf,c->overwrite,true);if(rc){close(pfd);free(leaf);return rc;}if(mkdirat(pfd,leaf,0700)){close(pfd);free(leaf);return DARC_E_IO;}}}else if(errno==ENOENT){if(mkdirat(pfd,leaf,0700)){close(pfd);free(leaf);return DARC_E_IO;}}else{close(pfd);free(leaf);return DARC_E_IO;}st->dirs++;close(pfd);free(leaf);return 0;}
static int restore_symlink(int rootfd,const DarcFlatEnt*e,const DarcConfig*c,RestoreStats*st){int pfd;char*leaf=NULL;int rc=split_parent(rootfd,e->path,true,&pfd,&leaf);if(rc)return rc;rc=prepare_replace(pfd,leaf,c->overwrite,false);if(rc){close(pfd);free(leaf);return rc;}char*target=darc_strndup((const char*)e->target,e->target_len);if(!target){close(pfd);free(leaf);return DARC_E_IO;}if(symlinkat(target,pfd,leaf)){free(target);close(pfd);free(leaf);return DARC_E_IO;}free(target);if(c->preserve_mtime){struct timespec ts[2];ts[0].tv_nsec=UTIME_OMIT;ts[0].tv_sec=0;ts[1]=ns_timespec(e->mtime_ns);(void)utimensat(pfd,leaf,ts,AT_SYMLINK_NOFOLLOW);}st->symlinks++;close(pfd);free(leaf);return 0;}
static int restore_hardlink(const char*repo,int rootfd,const DarcFlatEnt*e,const DarcConfig*c,const char*filter,RestoreStats*st){char*target=darc_strndup((const char*)e->target,e->target_len);if(!target)return DARC_E_IO;if(!darc_path_is_safe_archive(target)){free(target);return restore_escape("unsafe hardlink target path");}if(filter&&!selected(target,filter)){free(target);st->hl_degraded++;return restore_file(repo,rootfd,e,c,st);}int pfd;char*leaf=NULL;int rc=split_parent(rootfd,e->path,true,&pfd,&leaf);if(rc){free(target);return rc;}rc=prepare_replace(pfd,leaf,c->overwrite,false);if(rc){free(target);close(pfd);free(leaf);return rc;}/* validate target component-wise before linkat */int tp=-1;char*tl=NULL;rc=split_parent(rootfd,target,false,&tp,&tl);if(!rc){struct stat s;if(fstatat(tp,tl,&s,AT_SYMLINK_NOFOLLOW)||!S_ISREG(s.st_mode)||S_ISLNK(s.st_mode))rc=DARC_E_RESTORE;}if(!rc&&linkat(tp,tl,pfd,leaf,0))rc=DARC_E_IO;if(!rc)st->hardlinks++;if(tp>=0)close(tp);free(tl);free(target);close(pfd);free(leaf);return rc;}
static int apply_dir_meta(int rootfd,const DarcFlatEnt*e,const DarcConfig*c){int pfd;char*leaf=NULL;int rc=split_parent(rootfd,e->path,false,&pfd,&leaf);if(rc)return rc;int fd=openat(pfd,leaf,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(fd<0){close(pfd);free(leaf);return DARC_E_IO;}if(c->preserve_mode&&fchmod(fd,(mode_t)e->mode))rc=DARC_E_IO;if(!rc&&c->preserve_mtime){struct timespec ts[2];ts[0].tv_nsec=UTIME_OMIT;ts[0].tv_sec=0;ts[1]=ns_timespec(e->mtime_ns);if(futimens(fd,ts))rc=DARC_E_IO;}close(fd);close(pfd);free(leaf);return rc;}
static int dest_inside_repo(const char*repo,const char*to){char*rr=realpath(repo,NULL);if(!rr)return 0;char*tr=realpath(to,NULL);if(!tr){char*par=darc_dirname_dup(to);tr=par?realpath(par,NULL):NULL;free(par);}int bad=0;if(tr){size_t n=strlen(rr);bad=!strncmp(tr,rr,n)&&(tr[n]==0||tr[n]=='/');}free(rr);free(tr);return bad;}
int darc_cmd_restore(const char*repo,const DarcConfig*c,const char*sel,const char*to,const char*path){test_restore_write_max=0;if(!to)return DARC_E_USAGE;if(dest_inside_repo(repo,to)){darc_error(DARC_E_RESTORE,"E_RESTORE_ESCAPE","restore destination is inside repository");return DARC_E_RESTORE;}DarcCid sid;DarcSnapshotObj s;int rc=darc_resolve_snapshot(repo,sel,&sid,&s);if(rc)return rc;DarcFlatTree t;rc=darc_flatten_snapshot(repo,&s,&t);if(rc){darc_snapshot_free(&s);return rc;}if(path&&*path&&!darc_flat_find(&t,path)){darc_flat_free(&t);darc_snapshot_free(&s);return DARC_E_NOTFOUND;}if(darc_mkdir_p(to,0700)&&errno!=EEXIST){darc_flat_free(&t);darc_snapshot_free(&s);return DARC_E_IO;}int rootfd=open(to,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(rootfd<0){int e=errno;darc_flat_free(&t);darc_snapshot_free(&s);if(e==ELOOP||e==ENOTDIR)return restore_escape("restore destination is a symlink or non-directory");return DARC_E_RESTORE;}RestoreStats st;memset(&st,0,sizeof st);/* directories first */for(size_t i=0;i<t.n&&!rc;i++)if(selected(t.v[i].path,path)&&t.v[i].type==2){if(!darc_path_is_safe_archive(t.v[i].path)){rc=restore_escape("unsafe directory path in snapshot");break;}rc=ensure_dir(rootfd,&t.v[i],c,&st);}for(size_t i=0;i<t.n&&!rc;i++)if(selected(t.v[i].path,path)&&t.v[i].type==1)rc=restore_file(repo,rootfd,&t.v[i],c,&st);for(size_t i=0;i<t.n&&!rc;i++)if(selected(t.v[i].path,path)&&t.v[i].type==4)rc=c->create_hardlinks?restore_hardlink(repo,rootfd,&t.v[i],c,path,&st):restore_file(repo,rootfd,&t.v[i],c,&st);for(size_t i=0;i<t.n&&!rc;i++)if(selected(t.v[i].path,path)&&t.v[i].type==3)rc=restore_symlink(rootfd,&t.v[i],c,&st);for(size_t i=t.n;i-->0&&!rc;)if(selected(t.v[i].path,path)&&t.v[i].type==2)rc=apply_dir_meta(rootfd,&t.v[i],c);close(rootfd);char sh[65];darc_cid_hex(&sid,sh);if(!rc&&st.hl_degraded)fprintf(stderr,"W_HARDLINK_TOPOLOGY_DEGRADED: %llu selected hardlink member(s) restored as independent regular files because their primary was outside the selection\n",(unsigned long long)st.hl_degraded);if(!rc&&getenv("DARC_TEST_RESTORE_STATS"))fprintf(stderr,"DARC_TEST_RESTORE_WRITE_MAX=%zu chunks=%llu\n",test_restore_write_max,(unsigned long long)st.chunks);if(!rc){if(c->output_format==1){printf("{\"snapshot\":\"%s\",\"path\":",sh);if(path){char*jp=darc_json_escape_bytes((const uint8_t*)path,strlen(path));printf("%s",jp?jp:"null");free(jp);}else printf("null");printf(",\"files\":%llu,\"dirs\":%llu,\"symlinks\":%llu,\"hardlinks\":%llu,\"logical_bytes\":%llu,\"chunks_read\":%llu,\"chunks_reconstructed\":%llu,\"hardlink_degraded\":%llu,\"status\":\"SUCCESS\"}\n",(unsigned long long)st.files,(unsigned long long)st.dirs,(unsigned long long)st.symlinks,(unsigned long long)st.hardlinks,(unsigned long long)st.bytes,(unsigned long long)st.chunks,(unsigned long long)st.recovered,(unsigned long long)st.hl_degraded);}else if(c->output_format==2)printf("{\"record\":\"summary\",\"snapshot\":\"%s\",\"files\":%llu,\"dirs\":%llu,\"logical_bytes\":%llu,\"status\":\"SUCCESS\"}\n",sh,(unsigned long long)st.files,(unsigned long long)st.dirs,(unsigned long long)st.bytes);else printf("Restore %s: SUCCESS\n  subtree: %s\n  files=%llu dirs=%llu symlinks=%llu hardlinks=%llu\n  logical bytes=%llu chunks=%llu parity-reconstructed=%llu\n  partial hardlink topology fallbacks=%llu\n",sh,path?path:"/",(unsigned long long)st.files,(unsigned long long)st.dirs,(unsigned long long)st.symlinks,(unsigned long long)st.hardlinks,(unsigned long long)st.bytes,(unsigned long long)st.chunks,(unsigned long long)st.recovered,(unsigned long long)st.hl_degraded);}else if(!darc_last_error)darc_error(rc,rc==DARC_E_RESTORE?"E_RESTORE_CONFLICT":rc==DARC_E_UNRECOVERABLE?"E_UNRECOVERABLE":"E_OBJECT_CORRUPT","restore failed; no corrupt file is published");darc_flat_free(&t);darc_snapshot_free(&s);return rc;}
